mapper.select:

select

  distinct


from safety_fire_inspection_task_info




  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

SELECT a.TASK_NAME, a.WORK_STEP_NAME, a.WORK_DEPT_CODE, a.WORK_DEPT_NAME, a.RISK_LEVEL, a.TASK_CYCLE_BEGIN_DATE, a.TASK_CYCLE_END_DATE, a.TASK_ISSUED_TIME, a.EMP_NO, a.EMP_NAME, a.EMP_ORG_NAME_PATH, a.TASK_STATUS, a.TASK_COMPLETE_TIME, a.INSPECTION_RESULT, a.RECTIFICATION_RESULT, b.INSPECTION_CODE, b.INSPECTION_ITEM, b.INSPECTION_OBJECT, b.INSPECTION_CATEGORY, b.INSPECTION_SUB_DIMENSION, b.INSPECTION_CONTENT, b.INSPECTION_METHOD, b.INSPECTION_RESULT as inspectionResultDetail, b.INSPECTION_TIME, b.PROCESS_ID FROM safety_fire_inspection_task_info a LEFT JOIN safety_fire_inspection_task_info_detail b ON a.id = b.INSPECTION_TASK_ID where 1 = 1
and a.WORK_STEP_NAME like concat('%',#{workStepName,jdbcType=VARCHAR},'%')
and b.INSPECTION_ITEM like concat('%',#{inspectionItem,jdbcType=VARCHAR},'%')
and a.WORK_DEPT_CODE in
#{item}
and a.RISK_LEVEL = #{riskLevel,jdbcType=VARCHAR}
and a.TASK_STATUS = #{taskStatus,jdbcType=VARCHAR}
and (a.EMP_NO = #{empName,jdbcType=VARCHAR} or a.EMP_NAME like concat('%',#{empName,jdbcType=VARCHAR},'%'))
and a.TASK_CYCLE_BEGIN_DATE >= #{taskCycleBeginDate,jdbcType=VARCHAR}
and a.TASK_CYCLE_BEGIN_DATE <= #{taskCycleEndDate,jdbcType=VARCHAR}
ORDER BY a.TASK_ISSUED_TIME DESC

update.foreach:
update safety_fire_inspection_task_info
set
RECTIFICATION_RESULT = #{item.rectificationResult,jdbcType=VARCHAR},
INSPECTION_RESULT = #{item.inspectionResult,jdbcType=VARCHAR}
where ID = #{item.id,jdbcType=BIGINT}
